using WypozyczalniaSportowa.Data;
namespace WypozyczalniaSportowa.Application; public sealed class NotificationService : IDisposable { private readonly RentalApplicationService _service; private readonly AuditLogWriter _audit; public NotificationService(RentalApplicationService service, AuditLogWriter audit) { _service = service; _audit = audit; _service.RentalCreated += OnRentalCreated; } private void OnRentalCreated(object? sender, RentalCreatedEventArgs e) => _audit.Write(e.ToString()); public void Dispose() => _service.RentalCreated -= OnRentalCreated; public override string ToString() => "Powiadomienia wypożyczalni"; }
